'use strict';
// Built-in document renderer for the viewer (F3): docx, xlsx, pptx and OpenDocument (odt / ods / odp) -> safe HTML.
// No Word / Office / OS component is used: these formats are zip files with XML inside. Every piece of text is escaped here,
// only tags generated by this file reach the page.
const yauzl = require('yauzl');

const MAX_ENTRY = 40 * 1024 * 1024; // one unpacked part (document.xml, an image ...)
const MAX_IMG = 6 * 1024 * 1024; // images larger than this are replaced by a note
const MAX_ROWS = 1000, MAX_COLS = 60; // spreadsheet view limits

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// ------------------------------------------------------------------ zip access
function openZip(file) {
  return new Promise((res, rej) => yauzl.open(file, { lazyEntries: true, autoClose: false }, (e, z) => (e ? rej(e) : res(z))));
}
/** map: entry name -> entry (names kept with their case) */
function listEntries(z) {
  return new Promise((res, rej) => {
    const m = new Map();
    z.on('entry', (e) => { m.set(e.fileName, e); z.readEntry(); });
    z.on('end', () => res(m));
    z.on('error', rej);
    z.readEntry();
  });
}
function readEntry(z, entry) {
  return new Promise((res, rej) => {
    if (entry.uncompressedSize > MAX_ENTRY) return rej(new Error('part too large: ' + entry.fileName));
    z.openReadStream(entry, (e, s) => {
      if (e) return rej(e);
      const c = [];
      s.on('data', (d) => c.push(d));
      s.on('end', () => res(Buffer.concat(c)));
      s.on('error', rej);
    });
  });
}

// ------------------------------------------------------------------ tiny XML parser -> { name, attrs, kids[], text }
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };
const decode = (s) => s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, g) => {
  if (g[0] === '#') {
    const n = g[1] === 'x' || g[1] === 'X' ? parseInt(g.slice(2), 16) : parseInt(g.slice(1), 10);
    return Number.isFinite(n) && n > 0 && n < 0x110000 ? String.fromCodePoint(n) : '';
  }
  return ENT[g] !== undefined ? ENT[g] : m;
});
function parseXml(src) {
  const root = { name: '#root', attrs: {}, kids: [], text: '' };
  const stack = [root];
  const re = /<!--[\s\S]*?-->|<!\[CDATA\[([\s\S]*?)\]\]>|<\?[\s\S]*?\?>|<!DOCTYPE[^>]*>|<(\/?)([^\s/>]+)((?:[^>"']|"[^"]*"|'[^']*')*?)(\/?)>|([^<]+)/g;
  let m;
  while ((m = re.exec(src))) {
    const top = stack[stack.length - 1];
    if (m[1] !== undefined) { top.kids.push({ name: '#text', text: m[1] }); continue; }
    if (m[6] !== undefined) { if (m[6].trim() !== '' || /(^|:)t$|^text:/.test(top.name)) top.kids.push({ name: '#text', text: decode(m[6]) }); continue; }
    if (m[3] === undefined) continue;
    if (m[2]) { if (stack.length > 1) stack.pop(); continue; }
    const attrs = {};
    m[4].replace(/([^\s=]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g, (_x, k, a, b) => { attrs[k] = decode(a !== undefined ? a : b); return ''; });
    const node = { name: m[3], attrs, kids: [] };
    top.kids.push(node);
    if (!m[5]) stack.push(node);
  }
  return root;
}
const kids = (n, name) => (n ? n.kids.filter((k) => k.name === name) : []);
const kid = (n, name) => (n ? n.kids.find((k) => k.name === name) : undefined);
const find = (n, name, out = []) => { if (n && n.kids) for (const k of n.kids) { if (k.name === name) out.push(k); find(k, name, out); } return out; };
const textOf = (n) => (n ? (n.name === '#text' ? n.text : n.kids.map(textOf).join('')) : '');
const attr = (n, k) => (n && n.attrs ? n.attrs[k] : undefined);
const isOn = (n) => !!n && n.attrs['w:val'] !== '0' && n.attrs['w:val'] !== 'false' && n.attrs['w:val'] !== 'off';

const mime = (name) => {
  const e = (name.split('.').pop() || '').toLowerCase();
  return { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', bmp: 'image/bmp', svg: 'image/svg+xml', webp: 'image/webp' }[e] || '';
};
async function imageUri(z, entries, name) {
  const t = mime(name);
  const e = entries.get(name);
  if (!t || !e || t === 'image/svg+xml') return '';
  if (e.uncompressedSize > MAX_IMG) return '';
  return `data:${t};base64,${(await readEntry(z, e)).toString('base64')}`;
}
const dirOf = (p) => (p.includes('/') ? p.slice(0, p.lastIndexOf('/') + 1) : '');
function resolveRel(base, target) {
  if (target.startsWith('/')) return target.slice(1);
  const parts = (dirOf(base) + target).split('/');
  const out = [];
  for (const p of parts) { if (p === '..') out.pop(); else if (p && p !== '.') out.push(p); }
  return out.join('/');
}
async function readRels(z, entries, partPath) {
  const rp = dirOf(partPath) + '_rels/' + partPath.split('/').pop() + '.rels';
  const rels = {};
  if (entries.has(rp)) for (const r of find(parseXml((await readEntry(z, entries.get(rp))).toString('utf8')), 'Relationship')) rels[r.attrs.Id] = r.attrs;
  return rels;
}

// ------------------------------------------------------------------ DOCX
async function renderDocx(z, entries) {
  const part = 'word/document.xml';
  if (!entries.has(part)) throw new Error('word/document.xml is missing');
  const doc = parseXml((await readEntry(z, entries.get(part))).toString('utf8'));
  const rels = await readRels(z, entries, part);
  // style id -> name (headings)
  const styles = {};
  if (entries.has('word/styles.xml')) {
    for (const s of find(parseXml((await readEntry(z, entries.get('word/styles.xml'))).toString('utf8')), 'w:style')) {
      const nm = kid(s, 'w:name');
      if (nm) styles[s.attrs['w:styleId']] = (nm.attrs['w:val'] || '').toLowerCase();
    }
  }
  const imgCache = new Map();
  async function pic(rid) {
    const rel = rels[rid];
    if (!rel) return '';
    const target = resolveRel(part, rel.Target);
    if (!imgCache.has(target)) imgCache.set(target, await imageUri(z, entries, target));
    const uri = imgCache.get(target);
    return uri ? `<img src="${uri}" alt="">` : '<span class="d-note">[image]</span>';
  }
  async function runHtml(r) {
    const rpr = kid(r, 'w:rPr');
    let out = '';
    for (const c of r.kids) {
      if (c.name === 'w:t' || c.name === 'w:delText') out += esc(textOf(c));
      else if (c.name === 'w:tab') out += '&emsp;';
      else if (c.name === 'w:br' || c.name === 'w:cr') out += '<br>';
      else if (c.name === 'w:drawing' || c.name === 'w:pict') {
        for (const b of find(c, 'a:blip')) out += await pic(b.attrs['r:embed']);
        for (const b of find(c, 'v:imagedata')) out += await pic(b.attrs['r:id']);
      }
    }
    if (!out) return '';
    if (rpr) {
      if (isOn(kid(rpr, 'w:b'))) out = `<b>${out}</b>`;
      if (isOn(kid(rpr, 'w:i'))) out = `<i>${out}</i>`;
      const u = kid(rpr, 'w:u');
      if (u && u.attrs['w:val'] !== 'none') out = `<u>${out}</u>`;
      if (isOn(kid(rpr, 'w:strike'))) out = `<s>${out}</s>`;
      const va = kid(rpr, 'w:vertAlign');
      if (va && va.attrs['w:val'] === 'superscript') out = `<sup>${out}</sup>`;
      else if (va && va.attrs['w:val'] === 'subscript') out = `<sub>${out}</sub>`;
      const col = kid(rpr, 'w:color');
      if (col && /^[0-9a-f]{6}$/i.test(col.attrs['w:val'] || '')) out = `<span style="color:#${col.attrs['w:val']}">${out}</span>`;
    }
    return out;
  }
  async function inlineHtml(p) {
    let out = '';
    for (const c of p.kids) {
      if (c.name === 'w:r') out += await runHtml(c);
      else if (c.name === 'w:hyperlink' || c.name === 'w:smartTag' || c.name === 'w:ins' || c.name === 'w:sdt' || c.name === 'w:sdtContent') out += await inlineHtml(c);
      else if (c.name === 'w:fldSimple') out += await inlineHtml(c);
    }
    return out;
  }
  async function paraHtml(p) {
    const ppr = kid(p, 'w:pPr');
    const sid = attr(kid(ppr, 'w:pStyle'), 'w:val');
    const sname = (sid && styles[sid]) || (sid || '').toLowerCase();
    let tag = 'p';
    const hm = /^heading\s*(\d)/.exec(sname) || /^heading(\d)/.exec(sname);
    if (hm) tag = 'h' + Math.min(6, +hm[1]);
    else if (sname === 'title') tag = 'h1';
    else if (sname === 'subtitle') tag = 'h2';
    let inner = await inlineHtml(p);
    const num = kid(ppr, 'w:numPr');
    if (num) inner = `<span class="d-bullet">&bull;</span> ${inner}`;
    const jc = attr(kid(ppr, 'w:jc'), 'w:val');
    const style = jc === 'center' ? ' style="text-align:center"' : jc === 'right' ? ' style="text-align:right"' : '';
    const lvl = num ? parseInt(attr(kid(num, 'w:ilvl'), 'w:val') || '0', 10) : 0;
    const pad = num ? ` style="margin-left:${(lvl + 1) * 22}px${jc ? ';text-align:' + (jc === 'center' ? 'center' : 'right') : ''}"` : style;
    if (!inner.trim()) return '<p class="d-empty">&nbsp;</p>';
    return `<${tag}${pad}>${inner}</${tag}>`;
  }
  async function tableHtml(t) {
    let out = '<table class="d-table">';
    for (const tr of kids(t, 'w:tr')) {
      out += '<tr>';
      for (const tc of kids(tr, 'w:tc')) out += '<td>' + (await blocks(tc)) + '</td>';
      out += '</tr>';
    }
    return out + '</table>';
  }
  async function blocks(parent) {
    let out = '';
    for (const c of parent.kids) {
      if (c.name === 'w:p') out += await paraHtml(c);
      else if (c.name === 'w:tbl') out += await tableHtml(c);
      else if (c.name === 'w:sdt') out += await blocks(kid(c, 'w:sdtContent') || c);
    }
    return out;
  }
  const body = find(doc, 'w:body')[0];
  return `<div class="d-doc">${await blocks(body || doc)}</div>`;
}

// ------------------------------------------------------------------ XLSX
const colName = (i) => { let s = ''; for (i++; i > 0; i = Math.floor((i - 1) / 26)) s = String.fromCharCode(65 + ((i - 1) % 26)) + s; return s; };
const colIndex = (ref) => { const m = /^([A-Z]+)/i.exec(ref || ''); if (!m) return 0; let n = 0; for (const ch of m[1].toUpperCase()) n = n * 26 + ch.charCodeAt(0) - 64; return n - 1; };
const fmtNumber = (v) => { const n = Number(v); if (!Number.isFinite(n)) return v; return Number.isInteger(n) ? String(n) : String(Math.round(n * 1e10) / 1e10); };

async function renderXlsx(z, entries) {
  if (!entries.has('xl/workbook.xml')) throw new Error('xl/workbook.xml is missing');
  const wb = parseXml((await readEntry(z, entries.get('xl/workbook.xml'))).toString('utf8'));
  const rels = await readRels(z, entries, 'xl/workbook.xml');
  const shared = [];
  if (entries.has('xl/sharedStrings.xml')) for (const si of find(parseXml((await readEntry(z, entries.get('xl/sharedStrings.xml'))).toString('utf8')), 'si')) shared.push(find(si, 't').map(textOf).join(''));
  let out = '<div class="d-xlsx">';
  const sheets = find(wb, 'sheet');
  for (const sh of sheets) {
    const rel = rels[sh.attrs['r:id']];
    const part = rel ? resolveRel('xl/workbook.xml', rel.Target) : '';
    out += `<h3>${esc(sh.attrs.name || 'Sheet')}</h3>`;
    if (!part || !entries.has(part)) { out += '<p class="d-note">(empty)</p>'; continue; }
    const ws = parseXml((await readEntry(z, entries.get(part))).toString('utf8'));
    const rows = find(ws, 'row');
    let maxCol = 0;
    const grid = [];
    for (const r of rows.slice(0, MAX_ROWS)) {
      const ri = (parseInt(r.attrs.r, 10) || grid.length + 1) - 1;
      const row = {};
      for (const c of kids(r, 'c')) {
        const ci = colIndex(c.attrs.r);
        if (ci >= MAX_COLS) continue;
        const t = c.attrs.t;
        let v = textOf(kid(c, 'v'));
        if (t === 's') v = shared[+v] !== undefined ? shared[+v] : '';
        else if (t === 'inlineStr') v = find(c, 't').map(textOf).join('');
        else if (t === 'b') v = v === '1' ? 'TRUE' : 'FALSE';
        else if (!t || t === 'n') v = fmtNumber(v);
        row[ci] = { v, num: !t || t === 'n' };
        if (ci + 1 > maxCol) maxCol = ci + 1;
      }
      grid[ri] = row;
    }
    if (!maxCol) { out += '<p class="d-note">(empty)</p>'; continue; }
    out += '<table class="d-grid"><tr><th></th>' + Array.from({ length: maxCol }, (_x, i) => `<th>${colName(i)}</th>`).join('') + '</tr>';
    for (let i = 0; i < grid.length; i++) {
      if (!grid[i]) continue;
      out += `<tr><th>${i + 1}</th>`;
      for (let c = 0; c < maxCol; c++) { const cell = grid[i][c]; out += cell ? `<td${cell.num ? ' class="n"' : ''}>${esc(cell.v)}</td>` : '<td></td>'; }
      out += '</tr>';
    }
    out += '</table>';
    if (rows.length > MAX_ROWS) out += `<p class="d-note">... only the first ${MAX_ROWS} rows are shown</p>`;
  }
  return out + '</div>';
}

// ------------------------------------------------------------------ PPTX
async function renderPptx(z, entries) {
  const slides = [...entries.keys()].filter((n) => /^ppt\/slides\/slide\d+\.xml$/.test(n)).sort((a, b) => parseInt(a.replace(/\D/g, ''), 10) - parseInt(b.replace(/\D/g, ''), 10));
  if (!slides.length) throw new Error('no slides found');
  let out = '<div class="d-pptx">';
  let i = 0;
  for (const s of slides) {
    i++;
    const x = parseXml((await readEntry(z, entries.get(s))).toString('utf8'));
    out += `<section class="d-slide"><div class="d-slide-n">Slide ${i}</div>`;
    const rels = await readRels(z, entries, s);
    for (const sp of find(x, 'p:sp')) {
      const isTitle = find(sp, 'p:ph').some((p) => /title/i.test(p.attrs.type || ''));
      for (const p of find(sp, 'a:p')) {
        const t = find(p, 'a:t').map(textOf).join('');
        if (!t.trim()) continue;
        const bullet = !isTitle && kid(kid(p, 'a:pPr'), 'a:buChar');
        out += isTitle ? `<h2>${esc(t)}</h2>` : `<p>${bullet ? '&bull; ' : ''}${esc(t)}</p>`;
      }
    }
    for (const tbl of find(x, 'a:tbl')) {
      out += '<table class="d-table">';
      for (const tr of kids(tbl, 'a:tr')) out += '<tr>' + kids(tr, 'a:tc').map((tc) => `<td>${esc(find(tc, 'a:t').map(textOf).join(' '))}</td>`).join('') + '</tr>';
      out += '</table>';
    }
    for (const b of find(x, 'a:blip')) {
      const rel = rels[b.attrs['r:embed']];
      if (!rel) continue;
      const uri = await imageUri(z, entries, resolveRel(s, rel.Target));
      if (uri) out += `<img src="${uri}" alt="">`;
    }
    out += '</section>';
  }
  return out + '</div>';
}

// ------------------------------------------------------------------ OpenDocument (odt / ods / odp)
async function renderOdf(z, entries, ext) {
  if (!entries.has('content.xml')) throw new Error('content.xml is missing');
  const doc = parseXml((await readEntry(z, entries.get('content.xml'))).toString('utf8'));
  const inline = (n) => {
    let out = '';
    for (const c of n.kids) {
      if (c.name === '#text') out += esc(c.text);
      else if (c.name === 'text:s') out += '&nbsp;'.repeat(parseInt(c.attrs['text:c'] || '1', 10));
      else if (c.name === 'text:tab') out += '&emsp;';
      else if (c.name === 'text:line-break') out += '<br>';
      else if (c.name === 'text:span' || c.name === 'text:a') out += inline(c);
    }
    return out;
  };
  const block = (n) => {
    let out = '';
    for (const c of n.kids) {
      if (c.name === 'text:h') out += `<h${Math.min(6, parseInt(c.attrs['text:outline-level'] || '1', 10))}>${inline(c)}</h${Math.min(6, parseInt(c.attrs['text:outline-level'] || '1', 10))}>`;
      else if (c.name === 'text:p') { const h = inline(c); out += h.trim() ? `<p>${h}</p>` : '<p class="d-empty">&nbsp;</p>'; }
      else if (c.name === 'text:list') for (const li of find(c, 'text:list-item')) out += `<p style="margin-left:22px"><span class="d-bullet">&bull;</span> ${kids(li, 'text:p').map(inline).join('<br>')}</p>`;
      else if (c.name === 'table:table') out += '<table class="d-table">' + kids(c, 'table:table-row').map((r) => '<tr>' + kids(r, 'table:table-cell').map((tc) => `<td>${block(tc)}</td>`).join('') + '</tr>').join('') + '</table>';
      else if (c.name === 'text:section' || c.name === 'office:text' || c.name === 'draw:text-box') out += block(c);
    }
    return out;
  };
  if (ext === 'ods') {
    let out = '<div class="d-xlsx">';
    for (const t of find(doc, 'table:table')) {
      out += `<h3>${esc(t.attrs['table:name'] || 'Sheet')}</h3><table class="d-grid">`;
      let rowsN = 0;
      for (const r of kids(t, 'table:table-row')) {
        if (rowsN >= MAX_ROWS) { out += '</table><p class="d-note">... only the first rows are shown</p><table>'; break; }
        const cells = [];
        for (const c of kids(r, 'table:table-cell')) {
          const rep = Math.min(parseInt(c.attrs['table:number-columns-repeated'] || '1', 10), 20);
          const isNum = c.attrs['office:value-type'] === 'float' || c.attrs['office:value-type'] === 'percentage' || c.attrs['office:value-type'] === 'currency';
          const v = kids(c, 'text:p').map(textOf).join(' ');
          for (let i = 0; i < rep && cells.length < MAX_COLS; i++) cells.push(`<td${isNum ? ' class="n"' : ''}>${esc(v)}</td>`);
        }
        while (cells.length && cells[cells.length - 1] === '<td></td>') cells.pop();
        if (!cells.length) continue;
        rowsN++;
        out += `<tr>${cells.join('')}</tr>`;
      }
      out += '</table>';
    }
    return out + '</div>';
  }
  if (ext === 'odp') {
    let out = '<div class="d-pptx">';
    let i = 0;
    for (const pg of find(doc, 'draw:page')) {
      i++;
      out += `<section class="d-slide"><div class="d-slide-n">Slide ${i}</div>`;
      for (const p of find(pg, 'text:p')) { const h = inline(p); if (h.trim()) out += `<p>${h}</p>`; }
      out += '</section>';
    }
    return out + '</div>';
  }
  const bodyNode = find(doc, 'office:text')[0];
  return `<div class="d-doc">${bodyNode ? block(bodyNode) : ''}</div>`;
}

/** formats this module can show */
const SUPPORTED = new Set(['docx', 'docm', 'dotx', 'xlsx', 'xlsm', 'pptx', 'pptm', 'odt', 'ods', 'odp']);

async function render(file, ext) {
  ext = String(ext || '').toLowerCase();
  if (!SUPPORTED.has(ext)) return { error: 'unsupported document type' };
  let z;
  try {
    z = await openZip(file);
    const entries = await listEntries(z);
    let html;
    if (ext.startsWith('doc') || ext === 'dotx') html = await renderDocx(z, entries);
    else if (ext.startsWith('xls')) html = await renderXlsx(z, entries);
    else if (ext.startsWith('ppt')) html = await renderPptx(z, entries);
    else html = await renderOdf(z, entries, ext);
    return { html };
  } catch (e) {
    return { error: 'Cannot read this document: ' + e.message };
  } finally {
    try { if (z) z.close(); } catch {}
  }
}

module.exports = { render, SUPPORTED, parseXml };
